-- Synchronize every application permission definition into the database catalogue.
-- This is intentionally additive/updating by unique code: existing permission IDs
-- (and therefore all existing user/business-role overrides) are preserved.
-- Bulk Allow All validates the complete authorised set against this table, so
-- every code in permissions.catalog.ts must have a corresponding database row.

ON CONFLICT ("code") DO UPDATE
SET "module" = EXCLUDED."module",
    "action" = EXCLUDED."action",
    "description" = EXCLUDED."description";
